// Staff roles for the admin (P3-07). Full administrators use Medusa's built-in
// "Super Admin" role (policy `*:*`), so it is not redefined here.
//
// Policy keys are `${resource}:${operation}`. Every resource below was checked against
// the rbac_policy table generated by Medusa 2.21.2 (built-in resources x read/create/
// update/delete). drn-0004 refuses to create roles if any key is missing.

export type Operation = "read" | "create" | "update" | "delete"

const ALL: Operation[] = ["read", "create", "update", "delete"]

export const keys = (resources: string[], ops: Operation[]): string[] =>
  resources.flatMap((r) => ops.map((o) => `${r}:${o}`))

// Read access every staff role needs for the admin dashboard shell to load.
// TODO(需查證): confirm in the admin UI that each role can open its pages (P3-07 manual check).
const BASE_READ = keys(
  ["store", "store_locale", "region", "currency", "sales_channel", "stock_location", "notification"],
  ["read"]
)

export type RoleDefinition = {
  name: string
  description: string
  policyKeys: string[]
}

export const ROLE_DEFINITIONS: RoleDefinition[] = [
  {
    name: "operations",
    // Includes order:update, which also allows cancelling an order (auto-refunds captured
    // payments). Accepted for operations; Aki to confirm (docs/DEV_PLAN.md P3-07).
    description: "營運：訂單（含取消）、退貨、出貨、庫存、促銷活動",
    policyKeys: [
      ...BASE_READ,
      ...keys(
        ["order", "order_item", "order_change", "order_claim", "order_claim_item", "order_exchange", "return"],
        ALL
      ),
      ...keys(["return_reason"], ["read"]),
      ...keys(
        ["fulfillment", "shipping_option", "shipping_profile", "fulfillment_set", "service_zone"],
        ALL
      ),
      ...keys(["fulfillment_provider", "shipping_option_type"], ["read"]),
      ...keys(["inventory_item", "inventory_level", "reservation_item"], ALL),
      ...keys(["promotion", "campaign"], ALL),
      ...keys(["product", "product_variant", "customer", "customer_address", "customer_group", "payment"], ["read"]),
    ],
  },
  {
    name: "support",
    // No order:update: in 2.21.2 that policy unlocks POST /admin/orders/:id/cancel, whose
    // workflow refunds every captured payment. Cancellations go through operations.
    description: "客服：會員、訂單查詢、退換貨申請（不可取消訂單、不可退款）",
    policyKeys: [
      ...BASE_READ,
      ...keys(["customer", "customer_address"], ["read", "create", "update"]),
      ...keys(["customer_group"], ["read"]),
      ...keys(["order", "order_change"], ["read"]),
      ...keys(["order_item", "return_reason", "product", "product_variant", "payment"], ["read"]),
      ...keys(["return", "order_claim", "order_claim_item", "order_exchange"], ["read", "create", "update"]),
    ],
  },
  {
    name: "content_editor",
    // No create grants: POST /admin/products also needs price:create and
    // inventory_item:create, so product creation stays with Super Admin. No variant
    // update either: the hardened variant route requires price:update.
    description: "內容編輯：商品文字與圖片、翻譯（不可建立商品、不可改價；Blog 權限於 P6 加入）",
    policyKeys: [
      ...BASE_READ,
      ...keys(
        [
          "product",
          "product_option",
          "product_option_value",
          "product_tag",
          "product_type",
          "product_category",
          "product_collection",
        ],
        ["read", "update"]
      ),
      // Variants carry prices; variant batch routes may not check price:update.
      ...keys(["product_variant"], ["read"]),
      ...keys(["file"], ["read", "create", "delete"]),
      ...keys(["translation"], ["read", "create", "update"]),
      ...keys(["inventory_item"], ["read"]),
    ],
  },
  {
    name: "finance",
    // Refund and capture routes require refund:create / capture:create, which 2.21.2 does
    // not register as policies, so only Super Admin (*:*) can refund or capture.
    description: "財務：付款紀錄、價格與價格表（可讀訂單與促銷；退款／請款限 Super Admin）",
    policyKeys: [
      ...BASE_READ,
      ...keys(["payment", "payment_collection"], ["read", "create", "update"]),
      ...keys(["refund_reason", "price_list", "price"], ALL),
      ...keys(
        ["price_preference", "tax_rate", "tax_region", "tax_provider", "order", "return", "campaign", "promotion"],
        ["read"]
      ),
    ],
  },
]
